package edu.pe.cibertec.saibm.inventario.domain.service; import java.time.Instant; import edu.pe.cibertec.saibm.inventario.domain.exception.InventoryConflictException; import edu.pe.cibertec.saibm.inventario.domain.model.*; public final class InventoryStateMachine {public InventoryState transition(InventoryState current,InventoryOperation op,Instant expiry,Instant now){if(current!=InventoryState.HELD)throw new InventoryConflictException("Only a held operation can transition");if(now.isAfter(expiry)){if(op==InventoryOperation.COMMIT)throw new InventoryConflictException("Expired hold cannot be committed");return InventoryState.EXPIRED;}return op==InventoryOperation.COMMIT?InventoryState.COMMITTED:InventoryState.RELEASED;}}
